def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    if n < 5:
        if op[-1] == 'D':
            return 'D'
        if n == 4 and all(x == 'C' for x in op):
            return 'D'
        return 'C'

    if n == 5:
        if sum(1 for x in op if x == 'D') >= 3:
            return 'D'
        return 'C'

    op_c = sum(1 for x in op if x == 'C')
    op_d = n - op_c

    if op_d == 0:
        return 'D'
    if op_c == 0:
        return 'D'

    last_my = my[-1]
    last_opp = op[-1]

    d3 = 0
    if op[-1] == 'D':
        d3 += 1
    if op[-2] == 'D':
        d3 += 1
    if op[-3] == 'D':
        d3 += 1

    d5 = sum(1 for x in op[-5:] if x == 'D')

    if n >= 15 and op_d * 2 >= n:
        return 'D'
    if n >= 30 and op_d * 3 >= n * 2:
        return 'D'
    if d3 >= 3:
        return 'D'
    if d3 == 2 and op_d > max(3, n // 4):
        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            return 'C'
        if history[-2][0] == 'D' and history[-2][1] == 'C' and last_my == 'C':
            return 'C'
        if op_d <= max(3, n // 5) and d5 <= 3:
            return 'C'
        if op_c > op_d and d3 <= 1 and n >= 20:
            return 'C'
        return 'D'

    if op_d <= max(2, n // 8):
        return 'C'
    if d5 == 0:
        return 'C'
    if d3 >= 2 and op_d > max(2, n // 5):
        return 'D'
    return 'C'
